# -*- coding: utf-8 -*-
# N2 中文 tambahan 3 (3問) + 統合理解 tambahan (2問)
P1 = "Cari kalimat pendapat penulis (biasanya setelah しかし/だが/つまり) lalu cocokkan dengan parafrasenya."
P2 = "Soal alasan/指示語: baca kalimat sebelum dan sesudah bagian bergaris bawah; jawabannya hampir selalu di sana."
P3 = "Pilihan yang terlalu ekstrem (すべて・必ず・全く) atau memuat hal yang tak ada di teks hampir pasti salah."
PT = "Soal 統合: tandai pendapat A dan B secara terpisah, lalu cari titik temu/perbedaannya."
JN = 'Teks menengah (内容理解・中文)'; JT = 'Bacaan gabungan (統合理解)'
R = ['Tidak disebut dalam teks.', 'Berlawanan dengan isi teks.', 'Berlebihan / bukan pendapat penulis.']
def C(jp, id, qs):
    return dict(slot='chu', jenis=JN, jp=jp, id=id, qs=[(q, [ok] + w, 0, al, bu, R, [P2, P3, P1][i % 3]) for i, (q, ok, w, al, bu) in enumerate(qs)])
def X(jp, id, qs):
    return dict(slot='tou', jenis=JT, jp=jp, id=id, qs=[(q, [ok] + w, 0, al, bu, R, PT) for (q, ok, w, al, bu) in qs])
B = [
 C('ある町の商店街では、シャッターを閉めたままの店が増えていた。そこで、地元の大学生が空き店舗を借り、週末だけ営業する「チャレンジショップ」を始めた。\n　学生たちは、自分たちで商品を選び、値段を決め、客に説明する。最初は売れなかったが、商店街の店主たちが仕入れや接客のこつを教えるうちに、少しずつ客が増えた。\n　この取り組みの成果は、売り上げだけではない。学生は商売の難しさを実際に体験でき、店主は若者の発想から刺激を受けた。そして何より、通りに人が戻ってきたことで、商店街全体が明るくなったのである。',
   'Di sebuah pusat pertokoan jumlah toko yang rolling door-nya tertutup bertambah. Maka mahasiswa setempat menyewa toko kosong dan memulai "toko tantangan" yang buka hanya akhir pekan.\n Para mahasiswa memilih barang, menentukan harga, dan menjelaskan pada pelanggan sendiri. Awalnya tak laku, tetapi sambil para pemilik toko mengajarkan trik pembelian dan pelayanan, pelanggan perlahan bertambah.\n Hasil upaya ini bukan hanya penjualan. Mahasiswa bisa merasakan sulitnya berdagang, dan pemilik toko terangsang oleh gagasan anak muda. Terlebih orang kembali ke jalan sehingga seluruh pusat pertokoan menjadi cerah.',
   [('チャレンジショップを始めたのはだれか。','地元の大学生',['商店街の店主','町の役所','大手の企業'],'Pelaku.','地元の大学生が空き店舗を借り'),
    ('客が増えたのはなぜか。','店主たちが仕入れや接客のこつを教えたから',['値段を高くしたから','毎日営業したから','広告を出したから'],'Karena dibimbing.','こつを教えるうちに、少しずつ客が増えた'),
    ('筆者は、この取り組みの成果として何を挙げているか。','学生と店主が刺激を受け、商店街が明るくなったこと',['売り上げが大きく伸びたこと','大学が有名になったこと','空き店舗がなくなったこと'],'Hasil keseluruhan.','店主は若者の発想から刺激を受けた…商店街全体が明るくなった')]),
 C('「忙しい」という言葉は、漢字では「心を亡くす」と書く。確かに、仕事に追われていると、周りの人への気配りや、季節の変化を感じる余裕を失ってしまう。\n　私も以前は、忙しいことが、仕事ができる証拠だと思っていた。予定が詰まっているほど、自分が必要とされているようで、うれしかったのだ。\n　しかし、ある日、同僚から「最近、顔が怖いよ」と言われてはっとした。それ以来、私は、予定の間に十五分の空白を作ることにした。その時間にお茶を飲んだり、窓の外を眺めたりするだけで、気持ちがずいぶん楽になる。忙しさを減らすことはできなくても、心の余裕は自分で作れるのだと思う。',
   'Kata "isogashii (sibuk)" dalam kanji ditulis "kehilangan hati". Memang bila dikejar pekerjaan, kita kehilangan kepekaan pada orang sekitar dan kelonggaran merasakan pergantian musim.\n Saya dulu juga mengira sibuk adalah bukti mampu bekerja. Makin padat jadwal rasanya makin dibutuhkan sehingga senang.\n Namun suatu hari saya terkejut ketika rekan berkata "belakangan wajahmu menakutkan". Sejak itu saya membuat jeda lima belas menit di antara jadwal. Hanya dengan minum teh atau menatap luar jendela saat itu, hati jauh lebih ringan. Meski tak bisa mengurangi kesibukan, saya rasa kelonggaran hati bisa dibuat sendiri.',
   [('筆者は以前、忙しいことをどう考えていたか。','仕事ができる証拠だと考えていた',['悪いことだと考えていた','何も感じなかった','体に良いと考えていた'],'Dulu.','仕事ができる証拠だと思っていた'),
    ('筆者がはっとしたのはなぜか。','同僚に顔が怖いと言われたから',['仕事で失敗したから','予定が空いたから','健康診断を受けたから'],'Penyebab.','「最近、顔が怖いよ」と言われてはっとした'),
    ('筆者が今していることは何か。','予定の間に十五分の空白を作ること',['忙しさを完全になくすこと','同僚と話さないこと','仕事を休むこと'],'Kebiasaan.','予定の間に十五分の空白を作る')]),
 C('日本では、「おもてなし」が、客を心から迎える精神として知られている。しかし、おもてなしと「サービス」は、同じではないという意見がある。\n　サービスは、客が求めることに応える行為であり、対価として料金が発生する。一方、おもてなしは、客が口にしないことまで察して、先回りして気を配ることだという。例えば、雨の日に、客が帰る時間に合わせて、玄関の傘を整えておくような行為である。\n　もちろん、おもてなしにも限度がある。客が望まない親切は、かえって負担になるからだ。大切なのは、相手をよく観察し、その人にとって本当に必要なことは何かを考え続ける姿勢だろう。',
   'Di Jepang "omotenashi" dikenal sebagai semangat menyambut tamu dari hati. Namun ada pendapat bahwa omotenashi dan "layanan" tidak sama.\n Layanan adalah tindakan menanggapi yang diminta pelanggan dan sebagai imbalannya timbul biaya. Sebaliknya, omotenashi adalah mengerti bahkan yang tak diucapkan pelanggan dan memperhatikan lebih dulu. Contohnya merapikan payung di pintu sesuai waktu pulang tamu pada hari hujan.\n Tentu omotenashi pun ada batasnya. Kebaikan yang tak diinginkan tamu malah jadi beban. Yang penting adalah sikap mengamati lawan dengan baik dan terus memikirkan apa yang benar-benar diperlukan orang itu.',
   [('サービスの特徴として、文章に合うものはどれか。','客が求めることに応え、対価として料金が発生する',['客が言わないことを察する','料金を取らない','先回りして気を配る'],'Ciri layanan.','客が求めることに応える行為であり、対価として料金が発生'),
    ('おもてなしの例として挙げられているものはどれか。','雨の日に、客の帰る時間に合わせて傘を整えておくこと',['客に料金を請求すること','客に傘を売ること','客が頼んだ傘を渡すこと'],'Contoh.','客が帰る時間に合わせて、玄関の傘を整えておく'),
    ('筆者が大切だと考えていることは何か。','相手をよく観察し、本当に必要なことを考え続けること',['どんな親切でもすること','客の望みを聞かないこと','サービスをやめること'],'Pesan penulis.','相手をよく観察し…考え続ける姿勢')]),
 C('近年、都市部では「共働き」の家庭が増え、子どもを預ける保育園の不足が深刻になっている。入りたくても入れない「待機児童」の問題は、長年の課題だ。\n　国や自治体は、保育園の数を増やす努力を続けてきた。その結果、待機児童の数は減りつつある。しかし、新しい保育園を作るには、場所だけでなく、保育士の確保が欠かせない。保育士は、仕事の大変さに比べて給料が低いと言われ、辞める人も少なくない。\n　つまり、保育園を増やすだけでは、問題は解決しないのである。保育士が長く働き続けられるように、待遇を改善することが、これからの大きな課題だと言えよう。',
   'Belakangan di perkotaan keluarga "kerja berdua" bertambah dan kekurangan tempat penitipan anak menjadi serius. Masalah "anak antre" yang ingin masuk tetapi tak bisa sudah lama jadi tantangan.\n Pemerintah pusat dan daerah terus berupaya menambah jumlah tempat penitipan. Hasilnya jumlah anak antre mulai berkurang. Namun membuat tempat baru butuh bukan hanya lokasi tetapi juga memastikan pengasuh. Pengasuh dikatakan bergaji rendah dibanding beratnya pekerjaan dan tak sedikit yang berhenti.\n Artinya hanya menambah tempat penitipan tak menyelesaikan masalah. Memperbaiki perlakuan agar pengasuh bisa bekerja lama adalah tantangan besar ke depan.',
   [('待機児童とは、どんな子どもか。','入りたくても保育園に入れない子ども',['保育園を辞めた子ども','学校に行かない子ども','親が働いていない子ども'],'Definisi.','入りたくても入れない「待機児童」'),
    ('保育園を増やすときの問題として、文章は何を挙げているか。','保育士を確保するのが難しいこと',['場所が多すぎること','子どもが減っていること','国が反対していること'],'Masalah.','保育士の確保が欠かせない'),
    ('筆者の考えに合うものはどれか。','待遇を改善して、保育士が長く働けるようにすべきだ',['保育園の数を減らすべきだ','待機児童は解決済みだ','保育士の給料は十分だ'],'Pendapat.','待遇を改善することが、これからの大きな課題')]),
 C('日本語の「間」という言葉は、時間や空間の「あいだ」を意味するが、それだけではない。会話や音楽、舞台などでは、あえて何もしない「ほどよい空白」を指すことがある。\n　例えば、落語家は、話の途中で少し沈黙を入れて、観客の想像をかき立てる。もし、この間がなければ、話は早く進むが、面白さは半減してしまうだろう。\n　日常の会話でも、同じことが言える。相手が話し終わった後に、すぐ返事をせず、一呼吸おくと、「ちゃんと聞いてくれている」という印象を与えられる。間は、何もない時間ではなく、気持ちを伝える大切な時間なのである。',
   'Kata "ma" dalam bahasa Jepang berarti "antara" waktu atau ruang, tetapi bukan hanya itu. Dalam percakapan, musik, dan panggung kadang menunjuk "ruang kosong secukupnya" yang sengaja tak berbuat apa pun.\n Misalnya pelawak rakugo menyisipkan hening sejenak di tengah cerita untuk memancing imajinasi penonton. Tanpa jeda ini cerita cepat maju tetapi serunya berkurang setengah.\n Dalam percakapan sehari-hari sama. Setelah lawan selesai bicara, tak langsung membalas melainkan menarik napas sejenak memberi kesan "didengarkan dengan baik". Ma bukan waktu kosong, melainkan waktu penting menyampaikan perasaan.',
   [('落語家が話の途中で沈黙を入れるのはなぜか。','観客の想像をかき立てるため',['話を忘れたため','話を早く終えるため','観客を眠らせるため'],'Tujuan jeda.','観客の想像をかき立てる'),
    ('日常の会話で、一呼吸おくとどんな印象を与えられるか。','ちゃんと聞いてくれているという印象',['話を聞いていないという印象','急いでいるという印象','怒っているという印象'],'Kesan.','「ちゃんと聞いてくれている」という印象'),
    ('筆者は、間をどんなものだと考えているか。','気持ちを伝える大切な時間',['何もない無駄な時間','話を早く進める時間','相手を待たせる時間'],'Pandangan.','気持ちを伝える大切な時間')]),
 C('日本の国立公園では、近年、外国人観光客の増加に伴い、ごみや自然への影響が問題になっている。ある山では、頂上までの道が混雑し、登山道の外に出て植物を踏む人も出てきた。\n　そこで、山の管理者は、入山できる人数を制限し、事前に予約をしてもらう制度を導入した。同時に、多言語の看板を設置し、自然を守るためのルールを丁寧に伝えている。\n　制度の導入には、「自由に登れなくなる」という反対の声もあった。しかし、今のところ、植物の被害は減り、登山者からも「静かに登れるようになった」という評価が聞かれる。自然を守りながら楽しむためには、一定の制限も必要だということだろう。',
   'Di taman nasional Jepang belakangan, seiring bertambahnya turis asing, sampah dan dampak pada alam menjadi masalah. Di sebuah gunung jalan ke puncak ramai dan muncul orang keluar jalur pendakian menginjak tumbuhan.\n Maka pengelola gunung membatasi jumlah orang yang boleh masuk dan menerapkan sistem reservasi sebelumnya. Sekaligus memasang papan petunjuk multibahasa dan menyampaikan aturan menjaga alam dengan sopan.\n Penerapan sistem menimbulkan suara penentang "tak bisa mendaki bebas". Namun sejauh ini kerusakan tumbuhan berkurang dan pendaki pun menilai "bisa mendaki dengan tenang". Agar bisa menikmati sambil menjaga alam, rupanya batasan tertentu juga diperlukan.',
   [('山で問題になっていたことは何か。','道が混雑し、登山道の外で植物を踏む人がいたこと',['山が低すぎること','外国人が来なくなったこと','道が崩れたこと'],'Masalah.','登山道の外に出て植物を踏む人'),
    ('山の管理者が導入した制度はどれか。','入山人数を制限し、事前予約をしてもらう制度',['入山料を無料にする制度','夜間だけ入山できる制度','外国人の入山を禁止する制度'],'Sistem.','入山できる人数を制限し、事前に予約'),
    ('制度の導入後、どうなったか。','植物の被害が減り、静かに登れるという評価が出た',['反対がすべてなくなった','登山者が増えた','植物の被害が増えた'],'Hasil.','植物の被害は減り…静かに登れるようになった')]),
 C('料理が上手な人は、レシピを見なくても、味を調整できる。それは、材料や調味料の働きを理解しているからだ。例えば、塩は味を引き締め、砂糖は角を取り、酢はさっぱりした後味を与える。\n　初心者は、レシピ通りに作るのがよいと言われる。確かに、最初のうちは、分量を守ることで、失敗を避けられる。しかし、レシピに頼りすぎると、「なぜその量なのか」を考えなくなり、応用が利かなくなってしまう。\n　私が勧めたいのは、レシピ通りに一度作った後、少しだけ分量を変えて、味の違いを確かめることだ。小さな実験を重ねることで、味の感覚が磨かれ、やがて自分の味を作れるようになる。',
   'Orang yang pandai memasak bisa menyesuaikan rasa tanpa melihat resep. Itu karena memahami kerja bahan dan bumbu. Misalnya garam mengencangkan rasa, gula menghilangkan ketajaman, cuka memberi rasa akhir segar.\n Pemula dikatakan sebaiknya membuat sesuai resep. Memang di awal dengan menaati takaran bisa menghindari kegagalan. Namun terlalu bergantung pada resep membuat kita tak memikirkan "mengapa takarannya segitu" dan tak bisa mengaplikasikan.\n Yang ingin saya sarankan: setelah sekali membuat sesuai resep, ubah takaran sedikit dan periksa perbedaan rasa. Dengan menumpuk eksperimen kecil, kepekaan rasa terasah dan akhirnya bisa menciptakan rasa sendiri.',
   [('料理が上手な人が味を調整できるのはなぜか。','材料や調味料の働きを理解しているから',['高い材料を使うから','レシピを覚えているから','毎日料理するから'],'Alasan.','材料や調味料の働きを理解している'),
    ('レシピに頼りすぎるとどうなるか。','なぜその量なのかを考えなくなり、応用が利かなくなる',['失敗が増える','料理が早くなる','味が濃くなる'],'Akibat.','応用が利かなくなってしまう'),
    ('筆者が勧めていることは何か。','一度レシピ通りに作ってから、少し分量を変えて試すこと',['レシピを見ずに作ること','毎回同じ分量で作ること','高い調味料を使うこと'],'Saran.','少しだけ分量を変えて、味の違いを確かめる')]),
 C('大学で学ぶ内容と、社会で求められる能力との間には、ずれがあるとよく言われる。企業は「すぐに使える人材」を求め、大学は「学問の基礎」を教えたいと考える。\n　このずれを埋めるために、多くの大学が、企業と協力して、学生が実際の仕事を体験できる授業を取り入れている。学生は、授業で学んだ知識が、現場でどう使われるかを知ることができる。\n　ただし、大学の役割を、単なる就職の準備と考えるのは、狭すぎるだろう。社会が急速に変わる中では、特定の技術より、自分で考え、学び続ける力が重要になる。大学は、その土台を作る場であるべきだ。',
   'Sering dikatakan ada kesenjangan antara isi yang dipelajari di universitas dan kemampuan yang dituntut masyarakat. Perusahaan menginginkan "tenaga yang langsung bisa dipakai", sedangkan universitas ingin mengajarkan "dasar ilmu".\n Untuk menutup kesenjangan ini banyak universitas bekerja sama dengan perusahaan dan memasukkan kuliah di mana mahasiswa bisa mengalami pekerjaan nyata. Mahasiswa bisa tahu bagaimana pengetahuan kuliah dipakai di lapangan.\n Namun menganggap peran universitas sekadar persiapan kerja terlalu sempit. Di tengah masyarakat yang cepat berubah, kemampuan berpikir dan terus belajar sendiri lebih penting daripada teknik tertentu. Universitas seharusnya menjadi tempat membangun landasannya.',
   [('企業が大学に求めていることは何か。','すぐに使える人材を育てること',['学問の基礎を教えること','学生を減らすこと','研究だけをすること'],'Tuntutan perusahaan.','「すぐに使える人材」を求め'),
    ('多くの大学が取り入れている授業はどれか。','企業と協力し、実際の仕事を体験できる授業',['企業が授業料を払う授業','インターネットだけの授業','教員が仕事を体験する授業'],'Kuliah.','学生が実際の仕事を体験できる授業'),
    ('筆者は、大学の役割をどう考えているか。','自分で考え、学び続ける力の土台を作る場',['就職の準備だけをする場','特定の技術を教える場','企業の要求に従う場'],'Pandangan.','自分で考え、学び続ける力…その土台を作る場')]),
 C('「方言」は、その地域の人々の暮らしや文化が生んだ言葉だ。しかし、テレビや学校で標準語が使われることで、若い世代の間では、方言を話せない人が増えていると言われる。\n　ある県では、方言が消えることを心配して、小学校で地域の高齢者から方言を学ぶ授業を始めた。子どもたちは、昔の遊びや仕事を教えてもらいながら、その言葉に込められた意味を知る。\n　授業を受けた子どもからは、「おじいちゃんの言葉が分かるようになって、うれしい」という声が聞かれた。方言を守ることは、言葉だけでなく、地域の記憶や世代の絆を守ることにもつながっているのである。',
   '"Dialek" adalah bahasa yang lahir dari kehidupan dan budaya masyarakat setempat. Namun karena bahasa baku dipakai di televisi dan sekolah, dikatakan di generasi muda makin banyak yang tak bisa berdialek.\n Di sebuah prefektur, karena khawatir dialek hilang, SD memulai pelajaran mempelajari dialek dari lansia setempat. Anak-anak, sambil diajari permainan dan pekerjaan lama, mengetahui makna yang terkandung dalam kata itu.\n Dari anak yang mengikuti terdengar suara "senang jadi mengerti kata kakek". Menjaga dialek berhubungan dengan menjaga bukan hanya bahasa tetapi juga ingatan daerah dan ikatan antargenerasi.',
   [('若い世代で方言を話せない人が増えているのはなぜか。','テレビや学校で標準語が使われているから',['方言が難しいから','方言が禁止されたから','高齢者が少ないから'],'Sebab.','標準語が使われることで'),
    ('ある県の小学校で始まった授業はどれか。','地域の高齢者から方言を学ぶ授業',['標準語を学ぶ授業','外国語を学ぶ授業','方言を禁止する授業'],'Kuliah SD.','地域の高齢者から方言を学ぶ授業'),
    ('筆者は、方言を守ることにどんな意味があると考えているか。','地域の記憶や世代の絆を守ることにもなる',['標準語をなくすこと','言葉だけを守ること','古い遊びをやめること'],'Makna.','地域の記憶や世代の絆を守ることにもつながっている')]),
 C('私は、毎日の通勤電車の中で、本を読むことにしている。以前は、スマートフォンでニュースやSNSを見ていたが、気づくと、何も頭に残らないまま、時間だけが過ぎていた。\n　本を読み始めて半年がたつ。一日に読める量はわずかだが、積み重なると、月に二、三冊は読み終えられる。驚いたのは、本の内容が、仕事の悩みを解くヒントになることがあったことだ。\n　もちろん、スマートフォンを使うことが悪いわけではない。ただ、「何となく」使うのをやめ、時間の使い方を自分で選ぶようにしたことが、私の生活を少し豊かにしたと感じている。',
   'Saya membaca buku di kereta komuter tiap hari. Dulu saya melihat berita dan media sosial di ponsel, tetapi saat sadar tak ada yang tertinggal di kepala dan hanya waktu berlalu.\n Sudah setengah tahun sejak mulai membaca. Jumlah yang terbaca sehari sedikit, tetapi jika menumpuk bisa selesai dua-tiga buku sebulan. Yang mengejutkan, isi buku kadang jadi petunjuk menyelesaikan kerisauan pekerjaan.\n Tentu memakai ponsel bukan hal buruk. Hanya saja berhenti memakainya "sekadarnya" dan memilih sendiri cara memakai waktu, saya rasa memperkaya hidup sedikit.',
   [('以前、筆者は通勤電車の中で何をしていたか。','スマートフォンでニュースやSNSを見ていた',['本を読んでいた','寝ていた','仕事をしていた'],'Dulu.','スマートフォンでニュースやSNSを見ていた'),
    ('筆者が驚いたことは何か。','本の内容が仕事の悩みを解くヒントになったこと',['本が安かったこと','一日で何冊も読めたこと','電車が空いていたこと'],'Terkejut.','仕事の悩みを解くヒントになることがあった'),
    ('筆者が生活を豊かにしたと感じている理由は何か。','何となく使うのをやめ、時間の使い方を自分で選んだから',['スマートフォンをやめたから','本を買い集めたから','通勤時間が短くなったから'],'Alasan.','「何となく」使うのをやめ、時間の使い方を自分で選ぶ')]),
]
